from pathlib import Path
import re,json
R=Path(__file__).resolve().parent
W=R.parent/'propuesta_grafica_widgets/widgets'
def widget(n):
 s=(W/f'W{n:02}.html').read_text()
 return re.search(r'<section id="demo"[^>]*>(.*?)</section>',s,re.S)[1]
def eyebrow(t):return f'<p class="eyebrow">{t}</p>'
def title(t,sub='',k=''):
 return (eyebrow(k) if k else '')+f'<h1>{t}</h1>'+ (f'<p class="intro">{sub}</p>' if sub else '')
def link(t,url='L8.html',secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{t}</a>'
mark='<svg class="mark" viewBox="0 0 48 48" aria-hidden="true"><path d="M3 39h13V27h12V15h14V3M3 47h22V35h12V23h10M3 29h4V17h13V5" fill="none" stroke="currentColor" stroke-width="3"/></svg>'
logo=f'<a class="logo" href="L1.html" aria-label="Paynalton, Inicio">{mark}<span>Paynalton<span class="copper">.</span></span></a>'
def zone(name,ids,body,cls=''):
 return f'<section class="zone {cls}" data-zone="{name}" data-widgets="{ids}">{body}</section>'
def sectionhead(t,k=''):
 return f'<div class="section-heading">{eyebrow(k) if k else ""}<h2>{t}</h2></div>'
def row(t,p,url):return f'<a class="linked-row" href="{url}"><div><h3>{t}</h3><p>{p}</p></div><span aria-hidden="true">↗</span></a>'
def project(name,desc,num,target,topic='Integración de sistemas'):
 return f'<article class="project-card" id="{name.lower()}" data-title="{name.lower()} {desc.lower()}" data-type="proyecto" data-topic="{topic}"><div class="card-top"><span>{num} / PROYECTO</span><span aria-hidden="true">↗</span></div><a href="{target}"><h3>{name}</h3></a><p>{desc}</p><div class="card-bottom"><span class="tag">{topic}</span><a href="{target}" class="textlink">Explorar</a></div></article>'
def book(t,desc,target,num='01'):
 return f'<article class="book-card" data-title="{t.lower()} {desc.lower()}" data-type="obra" data-topic="Creación editorial"><div class="book-art"><span>{num}</span>{mark}<b>CUADERNO<br>DE EJEMPLO</b></div><div class="book-card-copy">{eyebrow("MUESTRA CONFIGURABLE")}<h3><a href="{target}">{t}</a></h3><p>{desc}</p><a class="textlink" href="{target}">Abrir lectura ↗</a></div></article>'
projects=[('Pipila','Una integración urgente que creció con nuevas necesidades.','01','L3.html','Integración de sistemas'),('Onix','De un sistema heredado a una operación integrada.','02','L2.html#onix','Modernización'),('GUACAMAYA','Creación editorial con personas y agentes de IA.','03','L2.html#guacamaya','Creación editorial')]
