def footer():return f'<footer class="site-footer" data-zone="Pie de página" data-widgets="W07 · W08"><div>{logo}<p>Desarrollo, ideas y creación editorial.</p></div><div><a href="L6.html">Explorar por temas</a><a href="L8.html">Contacto</a><a href="https://www.linkedin.com/in/paynalton">LinkedIn ↗</a><a href="https://github.com/paynalton">GitHub ↗</a></div><div><label><input type="checkbox" data-static checked> Escena estática</label><label><input type="checkbox" data-motion checked> Reducir movimiento</label><small>Paynalton · Taller nocturno</small></div></footer>'
