 if name!='Pipila':c=c.replace('<a href="'+target+'"><h3>', '<h3>') if False else c
 if name!='Pipila':
  c=c.replace(f'<a href="#{name.lower().replace(" ","-")}"><h3>{name}</h3></a>',f'<h3>{name}</h3>')
